<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted} from 'vue'
import {api} from './session'
import {ElMessage} from 'element-plus'
const props=defineProps<{profileId:string,campaignId?:string,groupId?:string}>(),emit=defineEmits(['close','done'])
const campaign=ref(props.campaignId||''),group=ref(props.groupId||''),options=ref<any>({campaigns:[],groups:[]}),q=ref(''),page=ref(1),total=ref(0),rows=ref<any[]>([]),selected=ref<any[]>([]),busy=ref(false),preview=ref<any>(null),result=ref<any>(null)
const groups=computed(()=>options.value.groups.filter((g:any)=>g.campaign_id===campaign.value))
let timer:ReturnType<typeof setTimeout>|undefined,closed=false
async function load(){try{const r=await api('/advertising/create/products?'+new URLSearchParams({profile_id:props.profileId,q:q.value,page:String(page.value),page_size:'10'}));rows.value=r.rows;total.value=r.total}catch(e){ElMessage.error((e as Error).message)}}
function choose(row:any,value:any){selected.value=selected.value.filter(r=>r.sku!==row.sku);if(value)selected.value.push(row);preview.value=null}
async function prepare(){busy.value=true;try{preview.value=await api('/advertising/create/preview',{profile_id:props.profileId,mode:'ad',campaign_id:campaign.value,adgroup_id:group.value,products:selected.value.map(r=>({sku:r.sku,asin:r.asin||''})),state:'ENABLED'})}catch(e){ElMessage.error((e as Error).message)}finally{busy.value=false}}
async function poll(){try{result.value=await api('/advertising/create/status/'+preview.value.id);if(result.value.status==='sending'&&!closed)timer=setTimeout(poll,2000);else if(result.value.status==='succeeded')emit('done')}catch(e){ElMessage.error((e as Error).message)}}
async function confirm(){busy.value=true;try{result.value=await api('/advertising/create/confirm',{id:preview.value.id});await poll()}catch(e){ElMessage.error((e as Error).message)}finally{busy.value=false}}
onMounted(async()=>{try{options.value=await api('/advertising/create/options?profile_id='+encodeURIComponent(props.profileId));await load()}catch(e){ElMessage.error((e as Error).message)}})
onUnmounted(()=>{closed=true;if(timer)clearTimeout(timer)})
</script>
<template><el-dialog :model-value="true" title="添加广告商品" width="860px" @close="emit('close')" :close-on-click-modal="false"><div v-loading="busy">
<template v-if="!preview"><div class="pickers"><el-select v-model="campaign" placeholder="选择广告活动" filterable @change="group=''" style="width:48%"><el-option v-for="c in options.campaigns" :key="c.id" :label="c.name" :value="c.id"/></el-select><el-select v-model="group" placeholder="选择广告组" filterable style="width:48%"><el-option v-for="g in groups" :key="g.id" :label="g.name" :value="g.id"/></el-select></div><el-input v-model="q" placeholder="搜索 ASIN / SKU / 商品名称" @keyup.enter="page=1;load()"><template #append><el-button @click="page=1;load()">搜索</el-button></template></el-input><el-table :data="rows"><el-table-column width="45"><template #default="{row}"><el-checkbox :model-value="selected.some(r=>r.sku===row.sku)" @change="(v:any)=>choose(row,v)"/></template></el-table-column><el-table-column label="商品"><template #default="{row}"><div class="product"><img v-if="row.image" :src="row.image"/><div>{{row.title||row.product_name}}<br/><b>{{row.asin}}</b> · {{row.sku}}</div></div></template></el-table-column></el-table><el-pagination v-model:current-page="page" :page-size="10" :total="total" @current-change="load" layout="prev,pager,next"/><p>已选择 {{selected.length}} 个商品</p></template>
<template v-else><el-alert title="将向所选广告组添加以下商品，商品广告状态为启用" :closable="false"/><p v-for="p in selected" :key="p.sku">{{p.asin}} · {{p.sku}}</p><el-alert v-if="result" :title="result.message" :type="result.status==='succeeded'?'success':result.status==='sending'?'info':'warning'" :closable="false"/></template>
</div><template #footer><el-button @click="emit('close')">关闭</el-button><el-button v-if="preview&&!result" @click="preview=null">返回修改</el-button><el-button v-if="!preview" type="primary" :disabled="!group||!selected.length" :loading="busy" @click="prepare">预览添加</el-button><el-button v-else-if="!result" type="primary" :loading="busy" @click="confirm">确认添加</el-button></template></el-dialog></template>
<style scoped>.pickers{display:flex;gap:12px;margin-bottom:14px}.product{display:flex;align-items:center;gap:12px}.product img{width:45px;height:45px;object-fit:contain}</style>
